package com.steam.if97

import com.steam.if97.core.If97
import org.junit.Assert.assertEquals
import org.junit.Assert.assertTrue
import org.junit.Test
import java.util.Locale

/**
 * Compares this Kotlin implementation against an independent reference
 * implementation (the Python `iapws` package, IAPWS-IF97 R7-97) for 300+
 * states covering the whole 10-180 bar / 100-600 degC grid of the app.
 *
 * The reference data is generated by tools/gen_oracle.py and stored in
 * src/test/resources/if97_oracle.csv.
 */
class OracleGridTest {

    private class Ref(
        val pBar: Double,
        val tC: Double,
        val region: Int,
        val v: Double,
        val h: Double,
        val u: Double,
        val s: Double,
        val cp: Double,
        val cv: Double,
        val w: Double,
        val alphaV: Double,
        val kappaT: Double,
        val z: Double
    )

    private fun load(): List<Ref> {
        val stream = javaClass.classLoader!!.getResourceAsStream("if97_oracle.csv")
            ?: error("if97_oracle.csv not found - run tools/gen_oracle.py")
        return stream.bufferedReader().useLines { lines ->
            lines.drop(1)
                .filter { it.isNotBlank() }
                .map { line ->
                    val f = line.split(",")
                    Ref(
                        f[0].toDouble(), f[1].toDouble(), f[2].toInt(),
                        f[3].toDouble(), f[4].toDouble(), f[5].toDouble(), f[6].toDouble(),
                        f[7].toDouble(), f[8].toDouble(), f[9].toDouble(),
                        f[10].toDouble(), f[11].toDouble(), f[12].toDouble()
                    )
                }
                .toList()
        }
    }

    private fun rel(label: String, expected: Double, actual: Double, tol: Double) {
        if (expected.isNaN()) return
        val scale = if (Math.abs(expected) < 1e-9) 1.0 else Math.abs(expected)
        val diff = Math.abs(actual - expected) / scale
        assertTrue(
            String.format(
                Locale.US, "%s: expected %.12g but was %.12g (rel %.2e)", label, expected, actual, diff
            ),
            diff <= tol
        )
    }

    @Test
    fun matchesReferenceOverTheWholeGrid() {
        val rows = load()
        assertTrue("oracle grid is too small: ${rows.size}", rows.size >= 300)

        var region3States = 0
        for (ref in rows) {
            val tag = String.format(Locale.US, "p=%.2f bar T=%.2f C", ref.pBar, ref.tC)
            val st = If97.state(ref.pBar, ref.tC)
            assertEquals("region $tag", ref.region, st.region)
            rel("v $tag", ref.v, st.v, 1e-6)
            rel("h $tag", ref.h, st.h, 1e-6)
            rel("u $tag", ref.u, st.u, 1e-6)
            rel("s $tag", ref.s, st.s, 1e-6)
            rel("cp $tag", ref.cp, st.cp, 1e-6)
            rel("cv $tag", ref.cv, st.cv, 1e-6)
            rel("w $tag", ref.w, st.w, 1e-6)
            rel("Z $tag", ref.z, st.z, 1e-6)
            // alpha_v and kappa_t of the oracle come from central differences of v
            rel("alpha_v $tag", ref.alphaV, st.alphaV, 1e-4)
            rel("kappa_t $tag", ref.kappaT, st.kappaT, 1e-4)
            if (st.region == 3) region3States++
        }
        println("compared ${rows.size} states, $region3States of them in region 3")
    }
}
